"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type LoopPrimitiveProps = ComponentProps<typeof motion.div>;

export function LoopPrimitive({ children, ...props }: LoopPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {rotate: -8}}
      animate={{rotate: 8}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 1.2, ease: [0.23, 1, 0.32, 1], repeat: Infinity, repeatType: "mirror" }}
      aria-hidden="true"
    >
      {children}
    </motion.div>
  );
}
